import { randomUUID } from 'node:crypto';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname } from 'node:path';

const DATA_FILE = new URL('./data/books.json', import.meta.url);

async function readAll() {
  try {
    const raw = await readFile(DATA_FILE, 'utf8');
    return JSON.parse(raw);
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function writeAll(books) {
  await mkdir(dirname(new URL(DATA_FILE).pathname), { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2));
}

export async function listBooks() {
  return readAll();
}

export async function getBook(id) {
  const books = await readAll();
  return books.find((b) => b.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const books = await readAll();
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: notes?.trim() ?? '',
    status: 'reading',
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await writeAll(books);
  return book;
}

export async function updateBook(id, changes) {
  const books = await readAll();
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return null;

  const book = books[index];
  if (changes.title !== undefined) book.title = changes.title.trim();
  if (changes.author !== undefined) book.author = changes.author.trim();
  if (changes.notes !== undefined) book.notes = changes.notes.trim();
  if (changes.status !== undefined) {
    book.status = changes.status;
    book.finishedAt = changes.status === 'finished' ? new Date().toISOString() : null;
  }

  books[index] = book;
  await writeAll(books);
  return book;
}

export async function deleteBook(id) {
  const books = await readAll();
  const next = books.filter((b) => b.id !== id);
  if (next.length === books.length) return false;
  await writeAll(next);
  return true;
}

