import express from 'express';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { addBook, deleteBook, getBook, listBooks, updateBook } from './store.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const PORT = process.env.PORT || 3000;

const app = express();
app.use(express.json());
app.use(express.static(join(__dirname, 'public')));

app.get('/api/books', async (req, res) => {
  res.json(await listBooks());
});

app.post('/api/books', async (req, res) => {
  const { title, author, notes } = req.body ?? {};
  if (!title?.trim() || !author?.trim()) {
    return res.status(400).json({ error: 'title and author are required' });
  }
  const book = await addBook({ title, author, notes });
  res.status(201).json(book);
});

app.get('/api/books/:id', async (req, res) => {
  const book = await getBook(req.params.id);
  if (!book) return res.status(404).json({ error: 'not found' });
  res.json(book);
});

app.patch('/api/books/:id', async (req, res) => {
  const book = await updateBook(req.params.id, req.body ?? {});
  if (!book) return res.status(404).json({ error: 'not found' });
  res.json(book);
});

app.delete('/api/books/:id', async (req, res) => {
  const ok = await deleteBook(req.params.id);
  if (!ok) return res.status(404).json({ error: 'not found' });
  res.status(204).end();
});

