async function loadBooks() {
  const res = await fetch('/api/books');
  const books = await res.json();

  const reading = books.filter((b) => b.status !== 'finished');
  const finished = books.filter((b) => b.status === 'finished');

  renderList(document.getElementById('reading-list'), reading, 'Nothing yet — add a book below.');
  renderList(document.getElementById('finished-list'), finished, 'No finished books yet.');
}

function renderList(el, books, emptyMessage) {
  el.innerHTML = '';
  if (books.length === 0) {
    const li = document.createElement('li');
    li.className = 'empty';
    li.textContent = emptyMessage;
    el.appendChild(li);
    return;
  }

  for (const book of books) {
    const li = document.createElement('li');
    const a = document.createElement('a');
    a.href = `/book/${book.id}`;

    const title = document.createElement('div');
    title.className = 'book-title';
    title.textContent = book.title;

    const author = document.createElement('div');
    author.className = 'book-author';
    author.textContent = book.author;

    a.append(title, author);
    li.appendChild(a);
    el.appendChild(li);
  }
}

document.getElementById('add-book').addEventListener('submit', async (e) => {
  e.preventDefault();
  const form = e.target;
  const data = Object.fromEntries(new FormData(form).entries());

  const res = await fetch('/api/books', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  });

  if (res.ok) {
    form.reset();
    loadBooks();
  } else {
    alert('Could not add book — title and author are required.');
  }
});

loadBooks();

