const id = window.location.pathname.split('/').pop();
const container = document.getElementById('book-detail');

async function loadBook() {
  const res = await fetch(`/api/books/${id}`);
  if (!res.ok) {
    container.textContent = 'Book not found.';
    return;
  }
  const book = await res.json();
  render(book);
}

function render(book) {
  container.innerHTML = '';
  document.title = book.title;

  const heading = document.createElement('h1');
  heading.textContent = book.title;
  const pill = document.createElement('span');
  pill.className = 'status-pill' + (book.status === 'finished' ? ' finished' : '');
  pill.textContent = book.status === 'finished' ? 'Finished' : 'Reading';
  heading.appendChild(pill);

  const author = document.createElement('div');
  author.className = 'book-author';
  author.textContent = book.author;

  const actions = document.createElement('div');
  actions.className = 'actions';
  const toggleBtn = document.createElement('button');
  toggleBtn.textContent = book.status === 'finished' ? 'Mark as reading' : 'Mark as finished';
  toggleBtn.addEventListener('click', async () => {
    const nextStatus = book.status === 'finished' ? 'reading' : 'finished';
    const res = await fetch(`/api/books/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: nextStatus }),
    });
    if (res.ok) render(await res.json());
  });
  actions.appendChild(toggleBtn);

  const notesBlock = document.createElement('div');
  notesBlock.className = 'notes-block';
  const notesHeading = document.createElement('h2');
  notesHeading.textContent = 'Notes';
  const notesArea = document.createElement('textarea');
  notesArea.value = book.notes ?? '';
  const saveBtn = document.createElement('button');
  saveBtn.textContent = 'Save notes';
  saveBtn.addEventListener('click', async () => {
    const res = await fetch(`/api/books/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ notes: notesArea.value }),
    });
    if (res.ok) {
      saveBtn.textContent = 'Saved';
      setTimeout(() => (saveBtn.textContent = 'Save notes'), 1200);
    }
  });
  notesBlock.append(notesHeading, notesArea, saveBtn);

  const shareBlock = document.createElement('div');
  shareBlock.className = 'notes-block';
  const shareHeading = document.createElement('h2');
  shareHeading.textContent = 'Share';
  const shareRow = document.createElement('div');
  shareRow.className = 'share-row';
  const shareInput = document.createElement('input');
  shareInput.readOnly = true;
  shareInput.value = window.location.href;
  const copyBtn = document.createElement('button');
  copyBtn.textContent = 'Copy link';
  copyBtn.addEventListener('click', async () => {
    await navigator.clipboard.writeText(shareInput.value);
    copyBtn.textContent = 'Copied';
    setTimeout(() => (copyBtn.textContent = 'Copy link'), 1200);
  });
  shareRow.append(shareInput, copyBtn);
  shareBlock.append(shareHeading, shareRow);

  container.append(heading, author, actions, notesBlock, shareBlock);
}

loadBook();

